    /**
     * Execute the console command.
     */
    public function handle()
    {
        Schema::disableForeignKeyConstraints();
        DB::table('tasks')->truncate();
        Schema::enableForeignKeyConstraints();

        foreach ($this->data() as $item) {
            Task::create([
                'type'           => $item[0],
                'id'             => $item[1],
                'equipment_name' => $item[3],
                'name'           => $item[4],
                'description'    => $item[5],
            ]);
        }
    }
